; Panasonic infrared frame (Kaseikyo, vendor 0x2002) with a 37 kHz carrier; one host word per frame (address, command, parity), acknowledged
; Generated by escgen from protocols/panasonic_tx.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: IRMP, irmpprotocols.h (KASEIKYO): a 3380 us start pulse and 1690 us pause, 423 us pulses, 1269 / 423 us pauses for 1 / 0, 48 bits LSB first, a stop bit; irmp.c checks the vendor parity nibble (XOR of the vendor's nibbles) and the last byte (XOR of bytes 2 to 4)
; Reference: Arduino-IRremote, ir_Kaseikyo.hpp: KASEIKYO_UNIT 432 us (16 periods of 37 kHz), an 8-unit header mark and 4-unit space, 1-unit marks, 3 / 1-unit spaces, <VendorID:16><VendorID parity:4><Address:12><Command:8><Parity:8>, PANASONIC_VENDOR_ID_CODE 0x2002, a 74 ms repeat distance
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.equ PERIOD, (CLK_KHZ * 10 + 185) // 370
.equ NBIT, 16
.equ NLEAD, 128
.equ HDR, 192 * PERIOD
.equ BIT0, 32 * PERIOD
.equ BIT1, 64 * PERIOD
.equ GAP, CLK_KHZ * 74
.equ C_PERIOD, PERIOD
.equ C_HIGH, (PERIOD + 1) // 3
.default PIN_IR, 0
.equ P_IR, 1 << PIN_IR

.own  PIN_IR, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_IR, 0, P_IR               ; idle levels
    ADDT  1
packet:
    POP   r1                          ; one word per packet (waits for the host)
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    LDLC  (NLEAD * PERIOD) // C_PERIOD ; leader: carrier pulses
    CALL  burst
    ADDT  HDR - NLEAD * PERIOD - 64   ; no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; one: carrier pulses
    CALL  burst
    ADDT  BIT1 - NBIT * PERIOD - 64   ; no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; one: carrier pulses
    CALL  burst
    ADDT  BIT1 - NBIT * PERIOD - 64   ; no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    MOVI  r3, 28                      ; 28 bits, LSB first, each zero or one
bit1:
    SHR   r1, 1                       ; C = the next bit
    JC    one2
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD        ; no change, no event
    JMP   next3
one2:
    LDLC  (NBIT * PERIOD) // C_PERIOD ; one: carrier pulses
    CALL  burst
    ADDT  BIT1 - NBIT * PERIOD - 64   ; no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
next3:
    MOVI  r0, 1
    SUB   r3, r0                      ; Z after the last bit
    JNZ   bit1
    LDLC  (NBIT * PERIOD) // C_PERIOD ; stop: carrier pulses
    CALL  burst
    ADDT  GAP - 64                    ; gap: no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    MOVI  r3, 1
    PUSH  r3                          ; packet sent
    JMP   packet

; ---- burst: lc carrier pulses from tmr; returns with tmr = start + lc * C_PERIOD
burst:
    EMIT  P_IR, P_IR, P_IR
    ADDT  C_HIGH
    EMIT  P_IR, 0, P_IR
    ADDT  C_PERIOD - C_HIGH
    DJNZ  burst
    RET
